window.MG_LAZY_DATA["data/lazy/owner-courses/d039-9e0a423746a746c2.json"]={sha256:"9e0a423746a746c2e27a43e7dce3429bfea2d1ed0552f82221de2fd86c15a72b",value:{"id":"d039","title":"海風蘇格蘭浮式風場","titleEn":"Hywind Scotland Floating Wind Farm","category":"energy","kind":"course","summary":"以spar 支撐、繫泊與浮式經驗遷移解析海風蘇格蘭浮式風場：六個原理與架構單元、十二項可保存的分析及驗證作業，附假想量化例、來源及衍生工程比較。","summaryEn":"Explore Hywind Scotland Floating Wind Farm through spar supports, mooring and floating-design transfer: six principle/architecture units and twelve saved analysis/validation tasks, with an assumed numerical example, primary sources and related engineering comparisons.","sourceIds":["v11x-scotland","v11x-nrel5"],"status":"guided","subcategory":"energy-wind","subcategoryTitle":"風輪與風電工程","subcategoryTitleEn":"Rotors and wind engineering","learningTrack":"energy","learningSubdiscipline":"energy-wind","learningTags":["energy","energy-wind","hywind-scotland"],"contentStatus":"reviewable-educational-curriculum","depth":4,"curriculumVersion":11,"stepCount":12,"estimatedMinutes":420,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"stages":[{"id":"d039-v11-stage1","order":1,"title":"系統邊界與基本原理","titleEn":"System boundaries and principles","description":"在海風蘇格蘭浮式風場案例中比較Scotland風分佈與海上rotor載荷，各完成分析及驗證。","descriptionEn":"Analyze and validate scotland wind distribution and offshore rotor loads within the Hywind Scotland Floating Wind Farm case.","steps":[{"id":"d039-v11-01","order":1,"sequence":1,"title":"風資源與功率包絡：架構分析","titleEn":"Wind resources and power envelopes: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-scotland","v11x-nrel5"],"prerequisiteIds":[],"objective":"針對Scotland風分佈提出可反駁的風資源與功率包絡模型與驗證紀錄。","objectiveEn":"Produce a falsifiable wind resources and power envelopes model and evidence record for scotland wind distribution.","instruction":"在「海風蘇格蘭浮式風場」的師傅示意與公開來源中，先辨識Scotland風分佈。可用風功率隨風速立方變化；風輪效率、額定及停機區間限制輸出。 建立風資源與功率包絡的輸入、狀態、輸出及邊界圖；本課重點是spar 支撐、繫泊與浮式經驗遷移。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。把風速分佈與假想功率曲線積分爲年能量。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify scotland wind distribution in the mentor diagram and primary sources for Hywind Scotland Floating Wind Farm. Available power scales cubically with speed; rotor efficiency, rating and shutdown regions limit output. Draw the inputs, states, outputs and boundaries of wind resources and power envelopes, focusing on spar supports, mooring and floating-design transfer. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Integrate a wind distribution with an assumed curve for annual energy. Record units, undisclosed parameters and model breakdown conditions.","observation":"把風速分佈與假想功率曲線積分爲年能量。","observationEn":"Integrate a wind distribution with an assumed curve for annual energy.","failure":"常見誤判：額定MW乘8760h就是實際年發電量。","failureEn":"Common misconception: Rated MW times 8760 hours equals actual annual generation.","check":"提交Scotland風分佈的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for scotland wind distribution.","knowledge":[{"id":"d039-v11-01-k1","title":"風資源與功率包絡","titleEn":"Wind resources and power envelopes","text":"可用風功率隨風速立方變化；風輪效率、額定及停機區間限制輸出。 本課架構對應：Scotland風分佈","textEn":"Available power scales cubically with speed; rotor efficiency, rating and shutdown regions limit output. Course architecture correspondence: Scotland wind distribution","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-01-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"把風速分佈與假想功率曲線積分爲年能量。 應逐項保留基準與不確定度；額定MW乘8760h就是實際年發電量。 是本單元要排除的誤解。","textEn":"Integrate a wind distribution with an assumed curve for annual energy. Retain each reference and uncertainty; reject the misconception: Rated MW times 8760 hours equals actual annual generation.","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-01-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"教學小型風輪假設ρ=1.225 kg/m³、面積90 m²、風速10 m/s、Cp=0.40，P=0.5ρAv³Cp=22.0500 kW。未含傳動電損、尾流、額定限值與風速分佈，不是本工程產品數值。","textEn":"Assume a teaching rotor with rho=1.225 kg/m³, A=90 m², v=10 m/s and Cp=0.40: P=22.0500 kW. Drivetrain/electrical loss, wakes, ratings and wind distributions are excluded; these are not project specifications.","sourceIds":["v11x-scotland","v11x-nrel5"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就Scotland風分佈的「風資源與功率包絡」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for wind resources and power envelopes in scotland wind distribution?","options":["可用風功率隨風速立方變化；風輪效率、額定及停機區間限制輸出。","額定MW乘8760h就是實際年發電量。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Available power scales cubically with speed; rotor efficiency, rating and shutdown regions limit output.","Rated MW times 8760 hours equals actual annual generation.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"可用風功率隨風速立方變化；風輪效率、額定及停機區間限制輸出。 把風速分佈與假想功率曲線積分爲年能量。","explanationEn":"Available power scales cubically with speed; rotor efficiency, rating and shutdown regions limit output. Integrate a wind distribution with an assumed curve for annual energy."}},{"id":"d039-v11-02","order":2,"sequence":2,"title":"風資源與功率包絡：證據驗證","titleEn":"Wind resources and power envelopes: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-scotland","v11x-nrel5"],"prerequisiteIds":["d039-v11-01"],"objective":"針對Scotland風分佈提出可反駁的風資源與功率包絡模型與驗證紀錄。","objectiveEn":"Produce a falsifiable wind resources and power envelopes model and evidence record for scotland wind distribution.","instruction":"沿用前一步「風資源與功率包絡」模型，檢查Scotland風分佈的兩個假想案例。把風速分佈與假想功率曲線積分爲年能量。 先訂可接受誤差，再比較預測與獨立計算；區分可用風功率隨風速立方變化；風輪效率、額定及停機區間限制輸出。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous wind resources and power envelopes model to inspect two hypothetical cases involving scotland wind distribution. Integrate a wind distribution with an assumed curve for annual energy. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Available power scales cubically with speed; rotor efficiency, rating and shutdown regions limit output.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"把風速分佈與假想功率曲線積分爲年能量。","observationEn":"Integrate a wind distribution with an assumed curve for annual energy.","failure":"常見誤判：額定MW乘8760h就是實際年發電量。","failureEn":"Common misconception: Rated MW times 8760 hours equals actual annual generation.","check":"提交Scotland風分佈的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for scotland wind distribution.","knowledge":[{"id":"d039-v11-02-k1","title":"風資源與功率包絡","titleEn":"Wind resources and power envelopes","text":"可用風功率隨風速立方變化；風輪效率、額定及停機區間限制輸出。 本課架構對應：Scotland風分佈","textEn":"Available power scales cubically with speed; rotor efficiency, rating and shutdown regions limit output. Course architecture correspondence: Scotland wind distribution","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-02-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"把風速分佈與假想功率曲線積分爲年能量。 應逐項保留基準與不確定度；額定MW乘8760h就是實際年發電量。 是本單元要排除的誤解。","textEn":"Integrate a wind distribution with an assumed curve for annual energy. Retain each reference and uncertainty; reject the misconception: Rated MW times 8760 hours equals actual annual generation.","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-02-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"教學小型風輪假設ρ=1.225 kg/m³、面積90 m²、風速10 m/s、Cp=0.40，P=0.5ρAv³Cp=22.0500 kW。未含傳動電損、尾流、額定限值與風速分佈，不是本工程產品數值。","textEn":"Assume a teaching rotor with rho=1.225 kg/m³, A=90 m², v=10 m/s and Cp=0.40: P=22.0500 kW. Drivetrain/electrical loss, wakes, ratings and wind distributions are excluded; these are not project specifications.","sourceIds":["v11x-scotland","v11x-nrel5"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就Scotland風分佈的「風資源與功率包絡」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for wind resources and power envelopes in scotland wind distribution?","options":["額定MW乘8760h就是實際年發電量。","把風速分佈與假想功率曲線積分爲年能量。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Rated MW times 8760 hours equals actual annual generation.","Integrate a wind distribution with an assumed curve for annual energy.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"可用風功率隨風速立方變化；風輪效率、額定及停機區間限制輸出。 把風速分佈與假想功率曲線積分爲年能量。","explanationEn":"Available power scales cubically with speed; rotor efficiency, rating and shutdown regions limit output. Integrate a wind distribution with an assumed curve for annual energy."}},{"id":"d039-v11-03","order":3,"sequence":3,"title":"葉片氣動與載荷：架構分析","titleEn":"Blade aerodynamics and loads: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-scotland","v11x-nrel5"],"prerequisiteIds":["d039-v11-02"],"objective":"針對海上rotor載荷提出可反駁的葉片氣動與載荷模型與驗證紀錄。","objectiveEn":"Produce a falsifiable blade aerodynamics and loads model and evidence record for offshore rotor loads.","instruction":"在「海風蘇格蘭浮式風場」的師傅示意與公開來源中，先辨識海上rotor載荷。扭轉、弦長與來流角共同影響升阻；輸出最優與疲勞最小未必同點。 建立葉片氣動與載荷的輸入、狀態、輸出及邊界圖；本課重點是spar 支撐、繫泊與浮式經驗遷移。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較兩組假想葉素的力與力矩方向。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify offshore rotor loads in the mentor diagram and primary sources for Hywind Scotland Floating Wind Farm. Twist, chord and inflow set lift/drag; maximum output and minimum fatigue need not coincide. Draw the inputs, states, outputs and boundaries of blade aerodynamics and loads, focusing on spar supports, mooring and floating-design transfer. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare force/moment directions for two assumed blade elements. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較兩組假想葉素的力與力矩方向。","observationEn":"Compare force/moment directions for two assumed blade elements.","failure":"常見誤判：提升瞬時功率必然減輕所有結構載荷。","failureEn":"Common misconception: More instantaneous power reduces every structural load.","check":"提交海上rotor載荷的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for offshore rotor loads.","knowledge":[{"id":"d039-v11-03-k1","title":"葉片氣動與載荷","titleEn":"Blade aerodynamics and loads","text":"扭轉、弦長與來流角共同影響升阻；輸出最優與疲勞最小未必同點。 本課架構對應：海上rotor載荷","textEn":"Twist, chord and inflow set lift/drag; maximum output and minimum fatigue need not coincide. Course architecture correspondence: Offshore rotor loads","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-03-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較兩組假想葉素的力與力矩方向。 應逐項保留基準與不確定度；提升瞬時功率必然減輕所有結構載荷。 是本單元要排除的誤解。","textEn":"Compare force/moment directions for two assumed blade elements. Retain each reference and uncertainty; reject the misconception: More instantaneous power reduces every structural load.","sourceIds":["v11x-scotland","v11x-nrel5"]}],"quiz":{"question":"就海上rotor載荷的「葉片氣動與載荷」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for blade aerodynamics and loads in offshore rotor loads?","options":["提升瞬時功率必然減輕所有結構載荷。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","扭轉、弦長與來流角共同影響升阻；輸出最優與疲勞最小未必同點。"],"optionsEn":["More instantaneous power reduces every structural load.","Equal case averages rule out spatial, temporal and model errors.","Twist, chord and inflow set lift/drag; maximum output and minimum fatigue need not coincide."],"answer":2,"explanation":"扭轉、弦長與來流角共同影響升阻；輸出最優與疲勞最小未必同點。 比較兩組假想葉素的力與力矩方向。","explanationEn":"Twist, chord and inflow set lift/drag; maximum output and minimum fatigue need not coincide. Compare force/moment directions for two assumed blade elements."}},{"id":"d039-v11-04","order":4,"sequence":4,"title":"葉片氣動與載荷：證據驗證","titleEn":"Blade aerodynamics and loads: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-scotland","v11x-nrel5"],"prerequisiteIds":["d039-v11-03"],"objective":"針對海上rotor載荷提出可反駁的葉片氣動與載荷模型與驗證紀錄。","objectiveEn":"Produce a falsifiable blade aerodynamics and loads model and evidence record for offshore rotor loads.","instruction":"沿用前一步「葉片氣動與載荷」模型，檢查海上rotor載荷的兩個假想案例。比較兩組假想葉素的力與力矩方向。 先訂可接受誤差，再比較預測與獨立計算；區分扭轉、弦長與來流角共同影響升阻；輸出最優與疲勞最小未必同點。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous blade aerodynamics and loads model to inspect two hypothetical cases involving offshore rotor loads. Compare force/moment directions for two assumed blade elements. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Twist, chord and inflow set lift/drag; maximum output and minimum fatigue need not coincide.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較兩組假想葉素的力與力矩方向。","observationEn":"Compare force/moment directions for two assumed blade elements.","failure":"常見誤判：提升瞬時功率必然減輕所有結構載荷。","failureEn":"Common misconception: More instantaneous power reduces every structural load.","check":"提交海上rotor載荷的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for offshore rotor loads.","knowledge":[{"id":"d039-v11-04-k1","title":"葉片氣動與載荷","titleEn":"Blade aerodynamics and loads","text":"扭轉、弦長與來流角共同影響升阻；輸出最優與疲勞最小未必同點。 本課架構對應：海上rotor載荷","textEn":"Twist, chord and inflow set lift/drag; maximum output and minimum fatigue need not coincide. Course architecture correspondence: Offshore rotor loads","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-04-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較兩組假想葉素的力與力矩方向。 應逐項保留基準與不確定度；提升瞬時功率必然減輕所有結構載荷。 是本單元要排除的誤解。","textEn":"Compare force/moment directions for two assumed blade elements. Retain each reference and uncertainty; reject the misconception: More instantaneous power reduces every structural load.","sourceIds":["v11x-scotland","v11x-nrel5"]}],"quiz":{"question":"就海上rotor載荷的「葉片氣動與載荷」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for blade aerodynamics and loads in offshore rotor loads?","options":["比較兩組假想葉素的力與力矩方向。","提升瞬時功率必然減輕所有結構載荷。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Compare force/moment directions for two assumed blade elements.","More instantaneous power reduces every structural load.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"扭轉、弦長與來流角共同影響升阻；輸出最優與疲勞最小未必同點。 比較兩組假想葉素的力與力矩方向。","explanationEn":"Twist, chord and inflow set lift/drag; maximum output and minimum fatigue need not coincide. Compare force/moment directions for two assumed blade elements."}}]},{"id":"d039-v11-stage2","order":2,"title":"功能架構與量化模型","titleEn":"Functional architecture and quantitative models","description":"在海風蘇格蘭浮式風場案例中比較風機電能轉換與spar與mooring，各完成分析及驗證。","descriptionEn":"Analyze and validate turbine electrical conversion and spar/mooring within the Hywind Scotland Floating Wind Farm case.","steps":[{"id":"d039-v11-05","order":1,"sequence":5,"title":"傳動與發電轉換：架構分析","titleEn":"Drivetrain and electrical conversion: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-scotland","v11x-nrel5"],"prerequisiteIds":["d039-v11-04"],"objective":"針對風機電能轉換提出可反駁的傳動與發電轉換模型與驗證紀錄。","objectiveEn":"Produce a falsifiable drivetrain and electrical conversion model and evidence record for turbine electrical conversion.","instruction":"在「海風蘇格蘭浮式風場」的師傅示意與公開來源中，先辨識風機電能轉換。齒輪、發電機與功率電子將低速力矩轉電；直驅與齒輪路線的負載分配不同。 建立傳動與發電轉換的輸入、狀態、輸出及邊界圖；本課重點是spar 支撐、繫泊與浮式經驗遷移。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。由給定轉速與功率計算軸扭矩並區分效率層。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify turbine electrical conversion in the mentor diagram and primary sources for Hywind Scotland Floating Wind Farm. Gearboxes, generators and converters turn slow torque into electricity; direct/geared routes distribute loads differently. Draw the inputs, states, outputs and boundaries of drivetrain and electrical conversion, focusing on spar supports, mooring and floating-design transfer. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Calculate shaft torque from assumed speed/power and separate efficiencies. Record units, undisclosed parameters and model breakdown conditions.","observation":"由給定轉速與功率計算軸扭矩並區分效率層。","observationEn":"Calculate shaft torque from assumed speed/power and separate efficiencies.","failure":"常見誤判：直驅代表無需發電機或功率電子。","failureEn":"Common misconception: Direct drive removes generators and power electronics.","check":"提交風機電能轉換的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for turbine electrical conversion.","knowledge":[{"id":"d039-v11-05-k1","title":"傳動與發電轉換","titleEn":"Drivetrain and electrical conversion","text":"齒輪、發電機與功率電子將低速力矩轉電；直驅與齒輪路線的負載分配不同。 本課架構對應：風機電能轉換","textEn":"Gearboxes, generators and converters turn slow torque into electricity; direct/geared routes distribute loads differently. Course architecture correspondence: Turbine electrical conversion","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-05-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"由給定轉速與功率計算軸扭矩並區分效率層。 應逐項保留基準與不確定度；直驅代表無需發電機或功率電子。 是本單元要排除的誤解。","textEn":"Calculate shaft torque from assumed speed/power and separate efficiencies. Retain each reference and uncertainty; reject the misconception: Direct drive removes generators and power electronics.","sourceIds":["v11x-scotland","v11x-nrel5"]}],"quiz":{"question":"就風機電能轉換的「傳動與發電轉換」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for drivetrain and electrical conversion in turbine electrical conversion?","options":["直驅代表無需發電機或功率電子。","齒輪、發電機與功率電子將低速力矩轉電；直驅與齒輪路線的負載分配不同。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Direct drive removes generators and power electronics.","Gearboxes, generators and converters turn slow torque into electricity; direct/geared routes distribute loads differently.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"齒輪、發電機與功率電子將低速力矩轉電；直驅與齒輪路線的負載分配不同。 由給定轉速與功率計算軸扭矩並區分效率層。","explanationEn":"Gearboxes, generators and converters turn slow torque into electricity; direct/geared routes distribute loads differently. Calculate shaft torque from assumed speed/power and separate efficiencies."}},{"id":"d039-v11-06","order":2,"sequence":6,"title":"傳動與發電轉換：證據驗證","titleEn":"Drivetrain and electrical conversion: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-scotland","v11x-nrel5"],"prerequisiteIds":["d039-v11-05"],"objective":"針對風機電能轉換提出可反駁的傳動與發電轉換模型與驗證紀錄。","objectiveEn":"Produce a falsifiable drivetrain and electrical conversion model and evidence record for turbine electrical conversion.","instruction":"沿用前一步「傳動與發電轉換」模型，檢查風機電能轉換的兩個假想案例。由給定轉速與功率計算軸扭矩並區分效率層。 先訂可接受誤差，再比較預測與獨立計算；區分齒輪、發電機與功率電子將低速力矩轉電；直驅與齒輪路線的負載分配不同。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous drivetrain and electrical conversion model to inspect two hypothetical cases involving turbine electrical conversion. Calculate shaft torque from assumed speed/power and separate efficiencies. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Gearboxes, generators and converters turn slow torque into electricity; direct/geared routes distribute loads differently.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"由給定轉速與功率計算軸扭矩並區分效率層。","observationEn":"Calculate shaft torque from assumed speed/power and separate efficiencies.","failure":"常見誤判：直驅代表無需發電機或功率電子。","failureEn":"Common misconception: Direct drive removes generators and power electronics.","check":"提交風機電能轉換的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for turbine electrical conversion.","knowledge":[{"id":"d039-v11-06-k1","title":"傳動與發電轉換","titleEn":"Drivetrain and electrical conversion","text":"齒輪、發電機與功率電子將低速力矩轉電；直驅與齒輪路線的負載分配不同。 本課架構對應：風機電能轉換","textEn":"Gearboxes, generators and converters turn slow torque into electricity; direct/geared routes distribute loads differently. Course architecture correspondence: Turbine electrical conversion","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-06-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"由給定轉速與功率計算軸扭矩並區分效率層。 應逐項保留基準與不確定度；直驅代表無需發電機或功率電子。 是本單元要排除的誤解。","textEn":"Calculate shaft torque from assumed speed/power and separate efficiencies. Retain each reference and uncertainty; reject the misconception: Direct drive removes generators and power electronics.","sourceIds":["v11x-scotland","v11x-nrel5"]}],"quiz":{"question":"就風機電能轉換的「傳動與發電轉換」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for drivetrain and electrical conversion in turbine electrical conversion?","options":["直驅代表無需發電機或功率電子。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","由給定轉速與功率計算軸扭矩並區分效率層。"],"optionsEn":["Direct drive removes generators and power electronics.","Equal case averages rule out spatial, temporal and model errors.","Calculate shaft torque from assumed speed/power and separate efficiencies."],"answer":2,"explanation":"齒輪、發電機與功率電子將低速力矩轉電；直驅與齒輪路線的負載分配不同。 由給定轉速與功率計算軸扭矩並區分效率層。","explanationEn":"Gearboxes, generators and converters turn slow torque into electricity; direct/geared routes distribute loads differently. Calculate shaft torque from assumed speed/power and separate efficiencies."}},{"id":"d039-v11-07","order":3,"sequence":7,"title":"支撐繫泊與動態：架構分析","titleEn":"Supports, mooring and dynamics: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-scotland","v11x-nrel5"],"prerequisiteIds":["d039-v11-06"],"objective":"針對spar與mooring提出可反駁的支撐繫泊與動態模型與驗證紀錄。","objectiveEn":"Produce a falsifiable supports, mooring and dynamics model and evidence record for spar/mooring.","instruction":"在「海風蘇格蘭浮式風場」的師傅示意與公開來源中，先辨識spar與mooring。固定與浮式支撐有不同模態；風浪流與繫泊共同影響塔和電纜運動。 建立支撐繫泊與動態的輸入、狀態、輸出及邊界圖；本課重點是spar 支撐、繫泊與浮式經驗遷移。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較固定與浮式假想模態圖及載荷組合。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify spar/mooring in the mentor diagram and primary sources for Hywind Scotland Floating Wind Farm. Fixed/floating supports differ in modes; wind, waves, currents and moorings affect motion. Draw the inputs, states, outputs and boundaries of supports, mooring and dynamics, focusing on spar supports, mooring and floating-design transfer. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare assumed fixed/floating mode maps and load combinations. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較固定與浮式假想模態圖及載荷組合。","observationEn":"Compare assumed fixed/floating mode maps and load combinations.","failure":"常見誤判：浮式風機可忽略波浪與繫泊。","failureEn":"Common misconception: Floating turbines can ignore waves and moorings.","check":"提交spar與mooring的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for spar/mooring.","knowledge":[{"id":"d039-v11-07-k1","title":"支撐繫泊與動態","titleEn":"Supports, mooring and dynamics","text":"固定與浮式支撐有不同模態；風浪流與繫泊共同影響塔和電纜運動。 本課架構對應：spar與mooring","textEn":"Fixed/floating supports differ in modes; wind, waves, currents and moorings affect motion. Course architecture correspondence: Spar/mooring","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-07-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較固定與浮式假想模態圖及載荷組合。 應逐項保留基準與不確定度；浮式風機可忽略波浪與繫泊。 是本單元要排除的誤解。","textEn":"Compare assumed fixed/floating mode maps and load combinations. Retain each reference and uncertainty; reject the misconception: Floating turbines can ignore waves and moorings.","sourceIds":["v11x-scotland","v11x-nrel5"]}],"quiz":{"question":"就spar與mooring的「支撐繫泊與動態」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for supports, mooring and dynamics in spar/mooring?","options":["固定與浮式支撐有不同模態；風浪流與繫泊共同影響塔和電纜運動。","浮式風機可忽略波浪與繫泊。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Fixed/floating supports differ in modes; wind, waves, currents and moorings affect motion.","Floating turbines can ignore waves and moorings.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"固定與浮式支撐有不同模態；風浪流與繫泊共同影響塔和電纜運動。 比較固定與浮式假想模態圖及載荷組合。","explanationEn":"Fixed/floating supports differ in modes; wind, waves, currents and moorings affect motion. Compare assumed fixed/floating mode maps and load combinations."}},{"id":"d039-v11-08","order":4,"sequence":8,"title":"支撐繫泊與動態：證據驗證","titleEn":"Supports, mooring and dynamics: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-scotland","v11x-nrel5"],"prerequisiteIds":["d039-v11-07"],"objective":"針對spar與mooring提出可反駁的支撐繫泊與動態模型與驗證紀錄。","objectiveEn":"Produce a falsifiable supports, mooring and dynamics model and evidence record for spar/mooring.","instruction":"沿用前一步「支撐繫泊與動態」模型，檢查spar與mooring的兩個假想案例。比較固定與浮式假想模態圖及載荷組合。 先訂可接受誤差，再比較預測與獨立計算；區分固定與浮式支撐有不同模態；風浪流與繫泊共同影響塔和電纜運動。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous supports, mooring and dynamics model to inspect two hypothetical cases involving spar/mooring. Compare assumed fixed/floating mode maps and load combinations. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Fixed/floating supports differ in modes; wind, waves, currents and moorings affect motion.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較固定與浮式假想模態圖及載荷組合。","observationEn":"Compare assumed fixed/floating mode maps and load combinations.","failure":"常見誤判：浮式風機可忽略波浪與繫泊。","failureEn":"Common misconception: Floating turbines can ignore waves and moorings.","check":"提交spar與mooring的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for spar/mooring.","knowledge":[{"id":"d039-v11-08-k1","title":"支撐繫泊與動態","titleEn":"Supports, mooring and dynamics","text":"固定與浮式支撐有不同模態；風浪流與繫泊共同影響塔和電纜運動。 本課架構對應：spar與mooring","textEn":"Fixed/floating supports differ in modes; wind, waves, currents and moorings affect motion. Course architecture correspondence: Spar/mooring","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-08-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較固定與浮式假想模態圖及載荷組合。 應逐項保留基準與不確定度；浮式風機可忽略波浪與繫泊。 是本單元要排除的誤解。","textEn":"Compare assumed fixed/floating mode maps and load combinations. Retain each reference and uncertainty; reject the misconception: Floating turbines can ignore waves and moorings.","sourceIds":["v11x-scotland","v11x-nrel5"]}],"quiz":{"question":"就spar與mooring的「支撐繫泊與動態」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for supports, mooring and dynamics in spar/mooring?","options":["浮式風機可忽略波浪與繫泊。","比較固定與浮式假想模態圖及載荷組合。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Floating turbines can ignore waves and moorings.","Compare assumed fixed/floating mode maps and load combinations.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"固定與浮式支撐有不同模態；風浪流與繫泊共同影響塔和電纜運動。 比較固定與浮式假想模態圖及載荷組合。","explanationEn":"Fixed/floating supports differ in modes; wind, waves, currents and moorings affect motion. Compare assumed fixed/floating mode maps and load combinations."}}]},{"id":"d039-v11-stage3","order":3,"title":"獨立驗證與工程交接","titleEn":"Independent validation and engineering handoff","description":"在海風蘇格蘭浮式風場案例中比較動態cable與陣列與長期capacity與availability，各完成分析及驗證。","descriptionEn":"Analyze and validate dynamic cable/array and long-term capacity/availability within the Hywind Scotland Floating Wind Farm case.","steps":[{"id":"d039-v11-09","order":1,"sequence":9,"title":"陣列尾流與海纜：架構分析","titleEn":"Array wakes and cables: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-scotland","v11x-nrel5"],"prerequisiteIds":["d039-v11-08"],"objective":"針對動態cable與陣列提出可反駁的陣列尾流與海纜模型與驗證紀錄。","objectiveEn":"Produce a falsifiable array wakes and cables model and evidence record for dynamic cable/array.","instruction":"在「海風蘇格蘭浮式風場」的師傅示意與公開來源中，先辨識動態cable與陣列。上游尾流影響下游風輪；陣列及出口海纜產生電損與可用率依賴。 建立陣列尾流與海纜的輸入、狀態、輸出及邊界圖；本課重點是spar 支撐、繫泊與浮式經驗遷移。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。分開氣動尾流損失、電纜損失及停機時數。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify dynamic cable/array in the mentor diagram and primary sources for Hywind Scotland Floating Wind Farm. Upstream wakes affect downwind rotors; array/export cables add losses and dependencies. Draw the inputs, states, outputs and boundaries of array wakes and cables, focusing on spar supports, mooring and floating-design transfer. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Separate wake loss, cable loss and downtime. Record units, undisclosed parameters and model breakdown conditions.","observation":"分開氣動尾流損失、電纜損失及停機時數。","observationEn":"Separate wake loss, cable loss and downtime.","failure":"常見誤判：風場效率就是單機效率與機組數相乘。","failureEn":"Common misconception: Farm efficiency is single-turbine efficiency times turbine count.","check":"提交動態cable與陣列的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for dynamic cable/array.","knowledge":[{"id":"d039-v11-09-k1","title":"陣列尾流與海纜","titleEn":"Array wakes and cables","text":"上游尾流影響下游風輪；陣列及出口海纜產生電損與可用率依賴。 本課架構對應：動態cable與陣列","textEn":"Upstream wakes affect downwind rotors; array/export cables add losses and dependencies. Course architecture correspondence: Dynamic cable/array","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-09-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"分開氣動尾流損失、電纜損失及停機時數。 應逐項保留基準與不確定度；風場效率就是單機效率與機組數相乘。 是本單元要排除的誤解。","textEn":"Separate wake loss, cable loss and downtime. Retain each reference and uncertainty; reject the misconception: Farm efficiency is single-turbine efficiency times turbine count.","sourceIds":["v11x-scotland","v11x-nrel5"]}],"quiz":{"question":"就動態cable與陣列的「陣列尾流與海纜」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for array wakes and cables in dynamic cable/array?","options":["風場效率就是單機效率與機組數相乘。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","上游尾流影響下游風輪；陣列及出口海纜產生電損與可用率依賴。"],"optionsEn":["Farm efficiency is single-turbine efficiency times turbine count.","Equal case averages rule out spatial, temporal and model errors.","Upstream wakes affect downwind rotors; array/export cables add losses and dependencies."],"answer":2,"explanation":"上游尾流影響下游風輪；陣列及出口海纜產生電損與可用率依賴。 分開氣動尾流損失、電纜損失及停機時數。","explanationEn":"Upstream wakes affect downwind rotors; array/export cables add losses and dependencies. Separate wake loss, cable loss and downtime."}},{"id":"d039-v11-10","order":2,"sequence":10,"title":"陣列尾流與海纜：證據驗證","titleEn":"Array wakes and cables: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-scotland","v11x-nrel5"],"prerequisiteIds":["d039-v11-09"],"objective":"針對動態cable與陣列提出可反駁的陣列尾流與海纜模型與驗證紀錄。","objectiveEn":"Produce a falsifiable array wakes and cables model and evidence record for dynamic cable/array.","instruction":"沿用前一步「陣列尾流與海纜」模型，檢查動態cable與陣列的兩個假想案例。分開氣動尾流損失、電纜損失及停機時數。 先訂可接受誤差，再比較預測與獨立計算；區分上游尾流影響下游風輪；陣列及出口海纜產生電損與可用率依賴。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous array wakes and cables model to inspect two hypothetical cases involving dynamic cable/array. Separate wake loss, cable loss and downtime. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Upstream wakes affect downwind rotors; array/export cables add losses and dependencies.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"分開氣動尾流損失、電纜損失及停機時數。","observationEn":"Separate wake loss, cable loss and downtime.","failure":"常見誤判：風場效率就是單機效率與機組數相乘。","failureEn":"Common misconception: Farm efficiency is single-turbine efficiency times turbine count.","check":"提交動態cable與陣列的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for dynamic cable/array.","knowledge":[{"id":"d039-v11-10-k1","title":"陣列尾流與海纜","titleEn":"Array wakes and cables","text":"上游尾流影響下游風輪；陣列及出口海纜產生電損與可用率依賴。 本課架構對應：動態cable與陣列","textEn":"Upstream wakes affect downwind rotors; array/export cables add losses and dependencies. Course architecture correspondence: Dynamic cable/array","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-10-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"分開氣動尾流損失、電纜損失及停機時數。 應逐項保留基準與不確定度；風場效率就是單機效率與機組數相乘。 是本單元要排除的誤解。","textEn":"Separate wake loss, cable loss and downtime. Retain each reference and uncertainty; reject the misconception: Farm efficiency is single-turbine efficiency times turbine count.","sourceIds":["v11x-scotland","v11x-nrel5"]}],"quiz":{"question":"就動態cable與陣列的「陣列尾流與海纜」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for array wakes and cables in dynamic cable/array?","options":["分開氣動尾流損失、電纜損失及停機時數。","風場效率就是單機效率與機組數相乘。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Separate wake loss, cable loss and downtime.","Farm efficiency is single-turbine efficiency times turbine count.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"上游尾流影響下游風輪；陣列及出口海纜產生電損與可用率依賴。 分開氣動尾流損失、電纜損失及停機時數。","explanationEn":"Upstream wakes affect downwind rotors; array/export cables add losses and dependencies. Separate wake loss, cable loss and downtime."}},{"id":"d039-v11-11","order":3,"sequence":11,"title":"監測維護與疲勞：架構分析","titleEn":"Monitoring, maintenance and fatigue: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-scotland","v11x-nrel5"],"prerequisiteIds":["d039-v11-10"],"objective":"針對長期capacity與availability提出可反駁的監測維護與疲勞模型與驗證紀錄。","objectiveEn":"Produce a falsifiable monitoring, maintenance and fatigue model and evidence record for long-term capacity/availability.","instruction":"在「海風蘇格蘭浮式風場」的師傅示意與公開來源中，先辨識長期capacity與availability。海上可達窗口及疲勞分佈影響可用率；一次滿功率測試不能驗證長期壽命。 建立監測維護與疲勞的輸入、狀態、輸出及邊界圖；本課重點是spar 支撐、繫泊與浮式經驗遷移。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。用假想時間序列比較容量因數、可用率及負載循環。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify long-term capacity/availability in the mentor diagram and primary sources for Hywind Scotland Floating Wind Farm. Access windows and fatigue distributions affect availability; one full-power test does not prove lifetime. Draw the inputs, states, outputs and boundaries of monitoring, maintenance and fatigue, focusing on spar supports, mooring and floating-design transfer. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare capacity factor, availability and cycles from assumed time series. Record units, undisclosed parameters and model breakdown conditions.","observation":"用假想時間序列比較容量因數、可用率及負載循環。","observationEn":"Compare capacity factor, availability and cycles from assumed time series.","failure":"常見誤判：容量因數與可用率是同一比例。","failureEn":"Common misconception: Capacity factor and availability are the same ratio.","check":"提交長期capacity與availability的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for long-term capacity/availability.","knowledge":[{"id":"d039-v11-11-k1","title":"監測維護與疲勞","titleEn":"Monitoring, maintenance and fatigue","text":"海上可達窗口及疲勞分佈影響可用率；一次滿功率測試不能驗證長期壽命。 本課架構對應：長期capacity與availability","textEn":"Access windows and fatigue distributions affect availability; one full-power test does not prove lifetime. Course architecture correspondence: Long-term capacity/availability","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-11-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"用假想時間序列比較容量因數、可用率及負載循環。 應逐項保留基準與不確定度；容量因數與可用率是同一比例。 是本單元要排除的誤解。","textEn":"Compare capacity factor, availability and cycles from assumed time series. Retain each reference and uncertainty; reject the misconception: Capacity factor and availability are the same ratio.","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-11-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"教學小型風輪假設ρ=1.225 kg/m³、面積90 m²、風速10 m/s、Cp=0.40，P=0.5ρAv³Cp=22.0500 kW。未含傳動電損、尾流、額定限值與風速分佈，不是本工程產品數值。","textEn":"Assume a teaching rotor with rho=1.225 kg/m³, A=90 m², v=10 m/s and Cp=0.40: P=22.0500 kW. Drivetrain/electrical loss, wakes, ratings and wind distributions are excluded; these are not project specifications.","sourceIds":["v11x-scotland","v11x-nrel5"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就長期capacity與availability的「監測維護與疲勞」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for monitoring, maintenance and fatigue in long-term capacity/availability?","options":["容量因數與可用率是同一比例。","海上可達窗口及疲勞分佈影響可用率；一次滿功率測試不能驗證長期壽命。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Capacity factor and availability are the same ratio.","Access windows and fatigue distributions affect availability; one full-power test does not prove lifetime.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"海上可達窗口及疲勞分佈影響可用率；一次滿功率測試不能驗證長期壽命。 用假想時間序列比較容量因數、可用率及負載循環。","explanationEn":"Access windows and fatigue distributions affect availability; one full-power test does not prove lifetime. Compare capacity factor, availability and cycles from assumed time series."}},{"id":"d039-v11-12","order":4,"sequence":12,"title":"監測維護與疲勞：證據驗證","titleEn":"Monitoring, maintenance and fatigue: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-scotland","v11x-nrel5"],"prerequisiteIds":["d039-v11-11"],"objective":"針對長期capacity與availability提出可反駁的監測維護與疲勞模型與驗證紀錄。","objectiveEn":"Produce a falsifiable monitoring, maintenance and fatigue model and evidence record for long-term capacity/availability.","instruction":"沿用前一步「監測維護與疲勞」模型，檢查長期capacity與availability的兩個假想案例。用假想時間序列比較容量因數、可用率及負載循環。 先訂可接受誤差，再比較預測與獨立計算；區分海上可達窗口及疲勞分佈影響可用率；一次滿功率測試不能驗證長期壽命。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous monitoring, maintenance and fatigue model to inspect two hypothetical cases involving long-term capacity/availability. Compare capacity factor, availability and cycles from assumed time series. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Access windows and fatigue distributions affect availability; one full-power test does not prove lifetime.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"用假想時間序列比較容量因數、可用率及負載循環。","observationEn":"Compare capacity factor, availability and cycles from assumed time series.","failure":"常見誤判：容量因數與可用率是同一比例。","failureEn":"Common misconception: Capacity factor and availability are the same ratio.","check":"提交長期capacity與availability的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for long-term capacity/availability.","knowledge":[{"id":"d039-v11-12-k1","title":"監測維護與疲勞","titleEn":"Monitoring, maintenance and fatigue","text":"海上可達窗口及疲勞分佈影響可用率；一次滿功率測試不能驗證長期壽命。 本課架構對應：長期capacity與availability","textEn":"Access windows and fatigue distributions affect availability; one full-power test does not prove lifetime. Course architecture correspondence: Long-term capacity/availability","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-12-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"用假想時間序列比較容量因數、可用率及負載循環。 應逐項保留基準與不確定度；容量因數與可用率是同一比例。 是本單元要排除的誤解。","textEn":"Compare capacity factor, availability and cycles from assumed time series. Retain each reference and uncertainty; reject the misconception: Capacity factor and availability are the same ratio.","sourceIds":["v11x-scotland","v11x-nrel5"]},{"id":"d039-v11-12-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"教學小型風輪假設ρ=1.225 kg/m³、面積90 m²、風速10 m/s、Cp=0.40，P=0.5ρAv³Cp=22.0500 kW。未含傳動電損、尾流、額定限值與風速分佈，不是本工程產品數值。","textEn":"Assume a teaching rotor with rho=1.225 kg/m³, A=90 m², v=10 m/s and Cp=0.40: P=22.0500 kW. Drivetrain/electrical loss, wakes, ratings and wind distributions are excluded; these are not project specifications.","sourceIds":["v11x-scotland","v11x-nrel5"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就長期capacity與availability的「監測維護與疲勞」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for monitoring, maintenance and fatigue in long-term capacity/availability?","options":["容量因數與可用率是同一比例。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","用假想時間序列比較容量因數、可用率及負載循環。"],"optionsEn":["Capacity factor and availability are the same ratio.","Equal case averages rule out spatial, temporal and model errors.","Compare capacity factor, availability and cycles from assumed time series."],"answer":2,"explanation":"海上可達窗口及疲勞分佈影響可用率；一次滿功率測試不能驗證長期壽命。 用假想時間序列比較容量因數、可用率及負載循環。","explanationEn":"Access windows and fatigue distributions affect availability; one full-power test does not prove lifetime. Compare capacity factor, availability and cycles from assumed time series."}}]}],"scope":"和平民用發電與融合研究的公開熱循環、功能架構及工程證據。核能不包含燃料製備、濃縮、武器、反應性整定或反應爐操作；地熱、風電及水力不提供未經場址驗證的施工／操作參數。算例皆是假想，實機由合格專業團隊依規範負責。","scopeEn":"Public thermal cycles, functional architecture and engineering evidence for peaceful generation/fusion research. Nuclear content excludes fuel production, enrichment, weapons, reactivity settings and reactor operations. Geothermal/wind/hydro supply no unverified construction/operation settings. Examples are hypothetical; qualified professionals govern actual equipment.","workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"教學小型風輪假設ρ=1.225 kg/m³、面積90 m²、風速10 m/s、Cp=0.40，P=0.5ρAv³Cp=22.0500 kW。未含傳動電損、尾流、額定限值與風速分佈，不是本工程產品數值。","textEn":"Assume a teaching rotor with rho=1.225 kg/m³, A=90 m², v=10 m/s and Cp=0.40: P=22.0500 kW. Drivetrain/electrical loss, wakes, ratings and wind distributions are excluded; these are not project specifications.","assumptions":"數值是本課自行設定的假設，不代表實機量測、產品額定或操作參數；改變模型邊界後必須重算。","assumptionsEn":"Inputs are independently selected assumptions, not measured hardware, ratings or operating parameters; recalculate after boundary changes.","sourceScope":"原創數值練習；來源支援公開架構及領域原理，不宣稱來源提供這組假想數據。","sourceScopeEn":"Original numerical exercise; sources support public architecture and principles, not these assumed measurements."},"diagram":{"type":"power","labels":["Scotland風分佈","海上rotor載荷","風機電能轉換","spar與mooring","動態cable與陣列","長期capacity與availability"],"labelsEn":["Scotland wind distribution","Offshore rotor loads","Turbine electrical conversion","Spar/mooring","Dynamic cable/array","Long-term capacity/availability"],"original":true,"notToScale":true},"vendorHints":[{"name":"Equinor","nameEn":"Equinor","url":"https://www.equinor.com/energy/hywind-scotland","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-scotland"]},{"name":"National Renewable Energy Laboratory","nameEn":"National Renewable Energy Laboratory","url":"https://www.nrel.gov/docs/fy09osti/38060.pdf","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-nrel5"]}],"architectureNodes":[["風輪葉片","Rotor blades"],["傳動與發電機","Drivetrain/generator"],["功率轉換","Power conversion"],["支撐或繫泊","Supports/mooring"],["陣列與海纜","Array/cables"]],"architectureEdges":[[0,1],[1,2],[2,4],[3,0],[3,1]],"architectureFamily":"wind","educationEdition":11,"enrichmentVersion":11}};
